      "Selve ruten er EWA Safari Outfitters' svar på et enkelt spørsmål: hvordan ville fastlandsruten se ut hvis hvert stopp måtte fortjene sin plass? Tarangire for elefantene og baobabtrærne. Et besøk hos et masai-samfunn og en mokoro-safari på Lake Manyara, et ekte tempoavbrekk mellom de større parkene. En full nedstigning i Ngorongoro-krateret, Afrikas mest pålitelige scene for Big Five. Og to hele dager i Serengeti, avsluttet fra luften.",
      "Vi er født i Tanzania og har base i Arusha, og denne reiseplanen er bygget opp av mange års erfaring på nettopp disse veiene og landingsstripene. Hver Crown Jewels-safari er skreddersydd etter deres datoer og tempo, ledet fra start til slutt av den samme profesjonelle, sertifiserte guiden, med 24/7-støtte bygget inn i stedet for lagt til i etterkant.",
