        "I noen få korte uker huser slettene rundt Ndutu en av de høyeste konsentrasjonene av sårbart ungt dyreliv noe sted på jorden — og hvert eneste rovdyr i miles omkrets vet nøyaktig hvor det skal være. Den spenningen former alt ved måten disse dagene fotograferes på. Kjøretøy holder posisjon i stedet for å kjøre videre raskt, fordi historien her ofte tar tid å utfolde seg: en gnuhunn som sirkler rundt en nyfødt som ennå ikke har funnet beina sine, en gepard som leser flokken fra en termitthaug, en sjakal som venter i utkanten på sitt øyeblikk. Guiden deres finner ikke bare dyreliv — de leser spenningen som bygger seg opp over slettene, og hjelper dere med å være i posisjon før den utløses.",
