      "To hele dager i Gombe er satt av til sjimpansetrekking, på de samme stiene hennes studier ble bygget på. Å nå Gombe krever en ekstra innenriks flystrekning og en sjøkryssing, logistikk som faller utenfor det de fleste operatører fokusert på den nordlige safariruten driver med til daglig, noe som er en del av grunnen til at denne kombinasjonen er uvanlig. De fleste Tanzania-operatører kjører enten en safari på den nordlige safariruten eller en strandforlengelse på Zanzibar — vi kjører begge halvdelene av denne turen som én sammenhengende bestilling, med samme guide gjennom hele turen, slik at reisende slipper å koordinere to separate operatører. For kunder som allerede har gjort en standard Tanzania-safari og ser etter hva som kommer etterpå, er denne reiseplanen bygget spesifikt for å svare på det.",
